using System.Security.Claims;
using System.Text.Json.Nodes;
public static class QuotePages
{
 public static bool Can(ClaimsPrincipal user,string action)=>AccessControl.Has(user,AccessPermissions.Prices,action)&&AccessControl.Has(user,AccessPermissions.Inquiries,action);
 public static void Map(WebApplication app){
  app.MapGet("/admin/quotes",(HttpContext c)=>Can(c.User,"view")?Results.Content(Editor(),"text/html; charset=utf-8"):Results.Forbid()).RequireAuthorization();
  app.MapGet("/admin/quotes/{id}/print",(string id,HttpContext c,Store store)=>!Can(c.User,"view")?Results.Forbid():store.QuoteById(id)==null?Results.NotFound():Results.Content(Print(),"text/html; charset=utf-8")).RequireAuthorization();
  app.MapGet("/api/admin/quotes",(HttpContext c,Store store)=>{
   if(!Can(c.User,"view"))return Results.Forbid();var state=store.Snapshot();JsonObject? inquiry=null;var inquiryId=c.Request.Query["inquiry"].ToString();
   if(inquiryId!=""){var row=store.InquiryById(inquiryId);if(row!=null)inquiry=InquiryPages.Data(row);}
   return Results.Json(new{quotes=store.QuoteList(),catalog=state["data"],inquiry,canEdit=Can(c.User,"edit")});
  }).RequireAuthorization();
  app.MapGet("/api/admin/quotes/{id}",(string id,HttpContext c,Store store)=>!Can(c.User,"view")?Results.Forbid():store.QuoteById(id) is JsonObject q?Results.Json(new{quote=q,settings=store.Snapshot()["data"]?["settings"]}):Results.NotFound()).RequireAuthorization();
  app.MapPost("/api/admin/quotes",async(HttpContext c,Store store)=>{
   if(!Can(c.User,"edit"))return Results.Forbid();try{var b=await c.Request.ReadFromJsonAsync<JsonObject>(c.RequestAborted)??throw new ArgumentException("Teklif bilgileri gerekli.");return Results.Json(new{quote=store.SaveQuote(b,AccessControl.DisplayName(c.User))});}
   catch(QuoteConflictException e){return Results.Json(new{error=e.Message},statusCode:409);}
  }).RequireAuthorization().RequireRateLimiting("public-write");
 }
